"""Query execution for minisql."""

import csv
import functools
import os
import re
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

from . import values
from .ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    In,
    IsNull,
    Like,
    Literal,
    Name,
    Select,
    Star,
    Unary,
)
from .errors import QueryError


@dataclass
class Result:
    columns: List[str]
    rows: List[Tuple[Any, ...]]


_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


# ---------------------------------------------------------------------------
# Tables


@dataclass
class _Table:
    name: str
    header: List[str]
    rows: List[List[Any]]

    def __post_init__(self) -> None:
        self._index: Dict[str, int] = {}
        for position, title in enumerate(self.header):
            # First occurrence wins for duplicate header names.
            self._index.setdefault(title.lower(), position)

    def index(self, column: str) -> int:
        """Resolve a column name case-insensitively to its header position."""
        try:
            return self._index[column.lower()]
        except KeyError:
            raise QueryError("unknown column: {}".format(column)) from None


def _convert(field: str) -> Any:
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory: str, name: str) -> _Table:
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table {!r} is empty".format(name)) from None

            rows: List[List[Any]] = []
            for record in reader:
                # csv.reader yields [] for a completely blank line.
                if not record:
                    continue
                if len(record) != len(header):
                    raise QueryError(
                        "table {!r}: row has {} fields, expected {}".format(
                            name, len(record), len(header)
                        )
                    )
                rows.append([_convert(field) for field in record])
    except QueryError:
        raise
    except (OSError, csv.Error, UnicodeDecodeError) as exc:
        raise QueryError(
            "could not read table {!r}: {}".format(name, exc)
        ) from exc

    return _Table(name, header, rows)


# ---------------------------------------------------------------------------
# Expression evaluation


def _is_aggregate(name: str) -> bool:
    return bool(values.is_aggregate(name))


def _require_bool(value: Any, op: str) -> Any:
    if value is not None and not isinstance(value, bool):
        raise QueryError("{} requires boolean operands".format(op))
    return value


def eval_expr(
    expr: Expr,
    row: Optional[List[Any]],
    table: _Table,
    group: Optional[List[List[Any]]],
) -> Any:
    """Evaluate ``expr`` for a row, or for a whole group of rows."""
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Name):
        if row is None:
            raise QueryError(
                "column {!r} is not available in this context".format(expr.name)
            )
        return row[table.index(expr.name)]

    if isinstance(expr, Star):
        raise QueryError("'*' is only allowed in COUNT(*)")

    if isinstance(expr, Unary):
        op = expr.op.upper()
        value = eval_expr(expr.operand, row, table, group)
        if op == "-":
            return values.negate(value)
        if op == "NOT":
            _require_bool(value, "NOT")
            return values.not3(value)
        raise QueryError("unknown unary operator: {}".format(expr.op))

    if isinstance(expr, Binary):
        op = expr.op.upper()
        if op in ("AND", "OR"):
            left = _require_bool(
                eval_expr(expr.left, row, table, group), op
            )
            right = _require_bool(
                eval_expr(expr.right, row, table, group), op
            )
            if op == "AND":
                return values.and3(left, right)
            return values.or3(left, right)

        left = eval_expr(expr.left, row, table, group)
        right = eval_expr(expr.right, row, table, group)
        if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            return values.compare(op, left, right)
        if op in ("+", "-", "*", "/"):
            return values.arithmetic(op, left, right)
        if op == "||":
            return values.concat(left, right)
        raise QueryError("unknown operator: {}".format(expr.op))

    if isinstance(expr, IsNull):
        value = eval_expr(expr.operand, row, table, group)
        result = value is None
        return not result if expr.negated else result

    if isinstance(expr, In):
        value = eval_expr(expr.operand, row, table, group)
        items = [eval_expr(item, row, table, group) for item in expr.items]
        result = values.in_list(value, items)
        return values.not3(result) if expr.negated else result

    if isinstance(expr, Between):
        value = eval_expr(expr.operand, row, table, group)
        low = eval_expr(expr.low, row, table, group)
        high = eval_expr(expr.high, row, table, group)
        result = values.between(value, low, high)
        return values.not3(result) if expr.negated else result

    if isinstance(expr, Like):
        value = eval_expr(expr.operand, row, table, group)
        pattern = eval_expr(expr.pattern, row, table, group)
        result = values.like(value, pattern)
        return values.not3(result) if expr.negated else result

    if isinstance(expr, Func):
        if _is_aggregate(expr.name):
            if group is None:
                raise QueryError(
                    "aggregate function {} used outside a grouped query".format(
                        expr.name
                    )
                )
            if len(expr.args) != 1:
                raise QueryError(
                    "aggregate function {} takes exactly one argument".format(
                        expr.name
                    )
                )
            argument = expr.args[0]
            if isinstance(argument, Star):
                if expr.name.lower() != "count":
                    raise QueryError("'*' is only allowed in COUNT(*)")
                return len(group)

            collected = [
                eval_expr(argument, group_row, table, None)
                for group_row in group
            ]
            return values.aggregate(expr.name, collected)

        arguments = [eval_expr(arg, row, table, group) for arg in expr.args]
        return values.scalar_function(expr.name, arguments)

    raise QueryError("unsupported expression: {!r}".format(expr))


# ---------------------------------------------------------------------------
# Structural helpers


def _children(expr: Expr) -> List[Expr]:
    if isinstance(expr, Unary):
        return [expr.operand]
    if isinstance(expr, Binary):
        return [expr.left, expr.right]
    if isinstance(expr, IsNull):
        return [expr.operand]
    if isinstance(expr, In):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, Func):
        return list(expr.args)
    return []


def _literal_key(value: Any) -> Any:
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        return ("float", value)
    if isinstance(value, str):
        return ("str", value)
    return ("value", type(value).__name__, repr(value))


def _operator_key(op: str) -> str:
    normalized = op.upper()
    # ``!=`` and ``<>`` are the same comparison.
    if normalized == "!=":
        return "<>"
    return normalized


def _canonical(expr: Expr) -> Any:
    """A hashable structural key for an expression.

    Names are case-insensitive and function/operator names are normalized.
    This is deliberately independent of ``Expr.text``.
    """
    if isinstance(expr, Literal):
        return ("literal", _literal_key(expr.value))
    if isinstance(expr, Name):
        return ("name", expr.name.lower())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, Unary):
        return ("unary", _operator_key(expr.op), _canonical(expr.operand))
    if isinstance(expr, Binary):
        return (
            "binary",
            _operator_key(expr.op),
            _canonical(expr.left),
            _canonical(expr.right),
        )
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, _canonical(expr.operand))
    if isinstance(expr, In):
        return (
            "in",
            expr.negated,
            _canonical(expr.operand),
            tuple(_canonical(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            _canonical(expr.operand),
            _canonical(expr.low),
            _canonical(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            expr.negated,
            _canonical(expr.operand),
            _canonical(expr.pattern),
        )
    if isinstance(expr, Func):
        return (
            "func",
            expr.name.lower(),
            tuple(_canonical(arg) for arg in expr.args),
        )
    return ("expr", repr(expr))


def _contains_aggregate(expr: Expr) -> bool:
    if isinstance(expr, Func) and _is_aggregate(expr.name):
        return True
    return any(_contains_aggregate(child) for child in _children(expr))


def _check_aggregate(expr: Expr) -> None:
    """Validate aggregate arity and reject nested aggregates."""
    if isinstance(expr, Func) and _is_aggregate(expr.name):
        if len(expr.args) != 1:
            raise QueryError(
                "aggregate function {} takes exactly one argument".format(
                    expr.name
                )
            )
        argument = expr.args[0]
        if isinstance(argument, Star):
            if expr.name.lower() != "count":
                raise QueryError("'*' is only allowed in COUNT(*)")
        elif _contains_aggregate(argument):
            raise QueryError("aggregate functions cannot be nested")

    for child in _children(expr):
        _check_aggregate(child)


def _validate_aggregates(select: Select) -> None:
    expressions: List[Expr] = [column.expr for column in select.columns]
    if select.where is not None:
        expressions.append(select.where)
    expressions.extend(select.group_by)
    if select.having is not None:
        expressions.append(select.having)
    expressions.extend(item.expr for item in select.order_by)

    for expr in expressions:
        _check_aggregate(expr)

    if select.where is not None and _contains_aggregate(select.where):
        raise QueryError("aggregate functions are not allowed in WHERE")
    for expr in select.group_by:
        if _contains_aggregate(expr):
            raise QueryError("aggregate functions are not allowed in GROUP BY")


def _validate_names(expr: Expr, table: _Table) -> None:
    if isinstance(expr, Name):
        table.index(expr.name)
    for child in _children(expr):
        _validate_names(child, table)


def _validate_grouped_names(expr: Expr, group_keys: set) -> None:
    # If the whole expression is one of the GROUP BY expressions, every
    # column it mentions is necessarily grouped.
    if _canonical(expr) in group_keys:
        return

    # Names inside an aggregate are exempt.
    if isinstance(expr, Func) and _is_aggregate(expr.name):
        return

    if isinstance(expr, Name):
        raise QueryError(
            "column {!r} must appear in GROUP BY or be used in an "
            "aggregate".format(expr.name)
        )

    for child in _children(expr):
        _validate_grouped_names(child, group_keys)


# ---------------------------------------------------------------------------
# SELECT list, output names, and ORDER BY references


def _expand_columns(select: Select, table: _Table) -> List[Column]:
    if not select.columns:
        raise QueryError("SELECT list is empty")

    star_columns = [
        column for column in select.columns if isinstance(column.expr, Star)
    ]
    if star_columns:
        if len(select.columns) != 1:
            raise QueryError("'*' must be the only select item")
        return [Column(Name(header)) for header in table.header]

    return list(select.columns)


def _output_name(column: Column, table: _Table) -> str:
    if column.alias is not None:
        return column.alias
    if isinstance(column.expr, Name):
        return table.header[table.index(column.expr.name)]
    return column.expr.text


def _resolve_order_refs(
    select: Select, output_names: List[str]
) -> List[Tuple[str, Any]]:
    """Resolve ORDER BY items to output positions or input expressions."""
    refs: List[Tuple[str, Any]] = []
    for item in select.order_by:
        expr = item.expr

        # A bare integer literal is a 1-based output column position.
        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            position = expr.value - 1
            if position < 0 or position >= len(output_names):
                raise QueryError(
                    "ORDER BY position {} is out of range".format(expr.value)
                )
            refs.append(("index", position))
            continue

        # A name matching an output column refers to that output column.
        if isinstance(expr, Name):
            lowered = expr.name.lower()
            for position, name in enumerate(output_names):
                if name.lower() == lowered:
                    refs.append(("index", position))
                    break
            else:
                refs.append(("expr", expr))
            continue

        refs.append(("expr", expr))

    return refs


# ---------------------------------------------------------------------------
# Records, grouping, and sorting


@dataclass
class _Record:
    row: Optional[List[Any]]
    group: Optional[List[List[Any]]]


def _build_records(
    rows: List[List[Any]],
    group_by: List[Expr],
    table: _Table,
    grouped: bool,
) -> List[_Record]:
    if not grouped:
        return [_Record(row, None) for row in rows]

    if not group_by:
        # All filtered rows form exactly one group, even when empty.
        return [_Record(rows[0] if rows else None, rows)]

    groups: Dict[Any, List[List[Any]]] = {}
    for row in rows:
        key_values = [
            eval_expr(expr, row, table, None) for expr in group_by
        ]
        key = values.row_key(key_values)
        groups.setdefault(key, []).append(row)

    return [_Record(group[0], group) for group in groups.values()]


def _compare_sort_keys(
    left: List[Any], right: List[Any], order_by: List[Any]
) -> int:
    for position, item in enumerate(order_by):
        a = left[position]
        b = right[position]

        if a is None and b is None:
            continue
        if a is None:
            # NULLs first ascending, last descending.
            return 1 if item.desc else -1
        if b is None:
            return -1 if item.desc else 1

        comparison = values.compare_for_sort(a, b)
        if comparison:
            return -comparison if item.desc else comparison

    return 0


# ---------------------------------------------------------------------------
# Execution


def execute(select: Select, directory: str) -> Result:
    """Execute a parsed SELECT against the CSV files in ``directory``."""
    table = _load_table(directory, select.table)

    # Aggregate rules (arity, nesting, WHERE/GROUP BY restrictions).
    _validate_aggregates(select)

    columns = _expand_columns(select, table)

    grouped = bool(select.group_by) or any(
        _contains_aggregate(column.expr) for column in columns
    )
    if not grouped and select.having is not None:
        grouped = _contains_aggregate(select.having)
    if not grouped:
        grouped = any(
            _contains_aggregate(item.expr) for item in select.order_by
        )

    output_names = [_output_name(column, table) for column in columns]
    order_refs = _resolve_order_refs(select, output_names)

    # Resolve every input column reference, even when there are no rows.
    for column in columns:
        _validate_names(column.expr, table)
    if select.where is not None:
        _validate_names(select.where, table)
    for expr in select.group_by:
        _validate_names(expr, table)
    if select.having is not None:
        _validate_names(select.having, table)
    for kind, value in order_refs:
        if kind == "expr":
            _validate_names(value, table)

    # WHERE: aggregates were already rejected.
    rows = table.rows
    if select.where is not None:
        filtered: List[List[Any]] = []
        for row in rows:
            if (
                values.condition(eval_expr(select.where, row, table, None))
                is True
            ):
                filtered.append(row)
        rows = filtered

    records = _build_records(rows, select.group_by, table, grouped)

    if grouped:
        group_keys = {_canonical(expr) for expr in select.group_by}
        for column in columns:
            _validate_grouped_names(column.expr, group_keys)
        if select.having is not None:
            _validate_grouped_names(select.having, group_keys)
        for kind, value in order_refs:
            if kind == "expr":
                _validate_grouped_names(value, group_keys)

    # HAVING: a group filter when grouped, otherwise an extra row filter.
    if select.having is not None:
        kept: List[_Record] = []
        for record in records:
            condition = eval_expr(
                select.having, record.row, table, record.group
            )
            if values.condition(condition) is True:
                kept.append(record)
        records = kept

    # Project output columns and compute ORDER BY keys for every record.
    projected: List[Tuple[List[Any], List[Any]]] = []
    for record in records:
        output = [
            eval_expr(column.expr, record.row, table, record.group)
            for column in columns
        ]
        sort_values: List[Any] = []
        for kind, value in order_refs:
            if kind == "index":
                sort_values.append(output[value])
            else:
                sort_values.append(
                    eval_expr(value, record.row, table, record.group)
                )
        projected.append((output, sort_values))

    # DISTINCT keeps the first occurrence, before sorting.
    if select.distinct:
        seen = set()
        unique: List[Tuple[List[Any], List[Any]]] = []
        for output, sort_values in projected:
            key = values.row_key(output)
            if key in seen:
                continue
            seen.add(key)
            unique.append((output, sort_values))
        projected = unique

    if select.order_by:
        projected.sort(
            key=functools.cmp_to_key(
                lambda left, right: _compare_sort_keys(
                    left[1], right[1], select.order_by
                )
            )
        )

    offset = select.offset if select.offset is not None else 0
    if offset < 0:
        raise QueryError("OFFSET must not be negative")

    if select.limit is not None:
        if select.limit < 0:
            raise QueryError("LIMIT must not be negative")
        projected = projected[offset:offset + select.limit]
    else:
        projected = projected[offset:]

    return Result(
        output_names,
        [tuple(output) for output, _ in projected],
    )

