import sys
import tempfile

sys.path.insert(0, "/private/tmp/tmpcxf4ohbk/pete/projects/minisql")

from minisql import values
from minisql.ast import (
    Between, Binary, Column, Func, In, IsNull, Like, Literal, Name,
    OrderItem, Select, Star, Unary,
)
from minisql.engine import execute
from minisql.errors import QueryError


# ---- reference values implementation (per SPEC) ----

def and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not3(a):
    if a is None:
        return None
    return not a


def condition(value):
    if value is True:
        return True
    if value is False or value is None:
        return False
    raise QueryError("condition must be boolean")


def _is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def arithmetic(op, a, b):
    if a is None or b is None:
        return None
    if not _is_num(a) or not _is_num(b):
        raise QueryError("arithmetic on non-numbers")
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            return None
        return a / b
    raise QueryError("bad arithmetic op")


def negate(a):
    if a is None:
        return None
    if not _is_num(a):
        raise QueryError("negate non-number")
    return -a


def concat(a, b):
    if a is None or b is None:
        return None
    if isinstance(a, bool) or isinstance(b, bool):
        raise QueryError("concat bool")
    return str(a) + str(b)


def _category(v):
    if isinstance(v, bool):
        return "bool"
    if _is_num(v):
        return "num"
    if isinstance(v, str):
        return "str"
    raise QueryError("bad value")


def compare(op, a, b):
    if a is None or b is None:
        return None
    ca, cb = _category(a), _category(b)
    if ca != cb:
        raise QueryError("cannot compare")
    if op == "=":
        return a == b
    if op in ("!=", "<>"):
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    raise QueryError("bad compare op")


def like(value, pattern):
    if value is None or pattern is None:
        return None
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError("LIKE requires strings")
    import re
    pieces = []
    for ch in pattern:
        if ch == "%":
            pieces.append(".*")
        elif ch == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(ch))
    return re.fullmatch("".join(pieces), value, re.S) is not None


def in_list(value, items):
    if value is None:
        return None
    saw_null = False
    for item in items:
        if item is None:
            saw_null = True
        elif compare("=", value, item) is True:
            return True
    return None if saw_null else False


def between(value, low, high):
    if value is None or low is None or high is None:
        return None
    return and3(compare(">=", value, low), compare("<=", value, high))


def scalar_function(name, args):
    n = name.lower()
    if n == "lower" and len(args) == 1:
        if args[0] is None:
            return None
        if not isinstance(args[0], str):
            raise QueryError("LOWER requires string")
        return args[0].lower()
    if n == "upper" and len(args) == 1:
        if args[0] is None:
            return None
        if not isinstance(args[0], str):
            raise QueryError("UPPER requires string")
        return args[0].upper()
    if n == "length" and len(args) == 1:
        if args[0] is None:
            return None
        if not isinstance(args[0], str):
            raise QueryError("LENGTH requires string")
        return len(args[0])
    if n == "abs" and len(args) == 1:
        if args[0] is None:
            return None
        if not _is_num(args[0]):
            raise QueryError("ABS requires number")
        return abs(args[0])
    if n == "round" and len(args) in (1, 2):
        x = args[0]
        if x is None:
            return None
        if not _is_num(x):
            raise QueryError("ROUND requires number")
        if len(args) == 1:
            return int(math.floor(x + 0.5)) if x >= 0 else -int(math.floor(-x + 0.5))
        d = args[1]
        if d is None:
            return None
        if not isinstance(d, int) or isinstance(d, bool):
            raise QueryError("ROUND digits must be int")
        factor = 10 ** d
        y = x * factor
        r = int(math.floor(y + 0.5)) if y >= 0 else -int(math.floor(-y + 0.5))
        return r / factor
    if n == "coalesce" and len(args) >= 1:
        for a in args:
            if a is not None:
                return a
        return None
    raise QueryError("unknown function")


_AGGS = {"count", "sum", "avg", "min", "max"}


def is_aggregate(name):
    return name.lower() in _AGGS


def aggregate(name, vals):
    n = name.lower()
    if n == "count":
        return sum(1 for v in vals if v is not None)
    nonnull = [v for v in vals if v is not None]
    if not nonnull:
        return None
    if n == "sum":
        total = nonnull[0]
        for v in nonnull[1:]:
            total = arithmetic("+", total, v)
        return total
    if n == "avg":
        total = nonnull[0]
        for v in nonnull[1:]:
            total = arithmetic("+", total, v)
        return arithmetic("/", total, len(nonnull))
    if n == "min":
        best = nonnull[0]
        for v in nonnull[1:]:
            if compare_for_sort(v, best) < 0:
                best = v
        return best
    if n == "max":
        best = nonnull[0]
        for v in nonnull[1:]:
            if compare_for_sort(v, best) > 0:
                best = v
        return best
    raise QueryError("unknown aggregate")


def compare_for_sort(a, b):
    if _is_num(a) and _is_num(b):
        return (a > b) - (a < b)
    if isinstance(a, str) and isinstance(b, str):
        return (a > b) - (a < b)
    if isinstance(a, bool) and isinstance(b, bool):
        return (a > b) - (a < b)
    raise QueryError("cannot sort mixed types")


def group_key(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if _is_num(value):
        return ("num", float(value))
    if isinstance(value, str):
        return ("str", value)
    return ("value", repr(value))


def row_key(vals):
    return tuple(group_key(v) for v in vals)


def to_text(value):
    return "" if value is None else str(value)


for _name, _fn in list(globals().items()):
    if _name in {
        "and3", "or3", "not3", "condition", "arithmetic", "negate",
        "concat", "compare", "like", "in_list", "between",
        "scalar_function", "is_aggregate", "aggregate",
        "compare_for_sort", "group_key", "row_key", "to_text",
    }:
        setattr(values, _name, _fn)


# ---- AST helpers ----

def lit(value, text=None):
    e = Literal(value)
    e.text = text if text is not None else repr(value)
    return e


def nm(name, text=None):
    e = Name(name)
    e.text = text if text is not None else name
    return e


def fn(name, *args, text=None):
    e = Func(name, list(args))
    e.text = text if text is not None else name + "()"
    return e


def un(op, operand, text=None):
    e = Unary(op, operand)
    e.text = text if text is not None else op + "x"
    return e


def bin(op, left, right, text=None):
    e = Binary(op, left, right)
    e.text = text if text is not None else "expr"
    return e


def col(expr, alias=None):
    return Column(expr, alias)


def order(expr, desc=False):
    return OrderItem(expr, desc)


def sel(columns, table, **kwargs):
    return Select(distinct=kwargs.pop("distinct", False), columns=columns,
                  table=table, **kwargs)


def check(label, result, expected_columns, expected_rows):
    ok = result.columns == expected_columns and result.rows == expected_rows
    print(("PASS " if ok else "FAIL ") + label)
    if not ok:
        print("  columns:", result.columns, "expected", expected_columns)
        print("  rows:", result.rows, "expected", expected_rows)
    return ok


def check_error(label, fn):
    try:
        fn()
    except QueryError as exc:
        print("PASS " + label + " (QueryError: {})".format(exc))
        return True
    except Exception as exc:
        print("FAIL " + label + " (wrong exception {!r})".format(exc))
        return False
    print("FAIL " + label + " (no error)")
    return False


def main():
    ok = True
    with tempfile.TemporaryDirectory() as d:
        with open(os.path.join(d, "t.csv"), "w", newline="") as f:
            f.write("id,name,category,price\n")
            f.write("1,widget,tools,25\n")
            f.write("2,gadget,toys,12.5\n")
            f.write("3,doohickey,tools,7\n")
            f.write("4,,toys,\n")
            f.write("\n")
        with open(os.path.join(d, "empty.csv"), "w") as f:
            pass
        with open(os.path.join(d, "bad.csv"), "w") as f:
            f.write("a,b\n1,2\n3\n")
        with open(os.path.join(d, "n.csv"), "w", newline="") as f:
            f.write("a,b,c\n-2,1.5,hello\n0,.5,3\n,1.,x\n")

        # basic projection / where / order
        q = sel([col(nm("name")), col(nm("price"))], "t",
                where=bin(">", nm("price"), lit(10)),
                order_by=[order(nm("price"), True)])
        ok &= check("basic", execute(q, d), ["name", "price"],
                    [("widget", 25), ("gadget", 12.5)])

        # case-insensitive header + output spelling
        ok &= check("case header", execute(sel([col(nm("NAME"))], "t"), d),
                    ["name"], [("widget",), ("gadget",), ("doohickey",), (None,)])

        # star
        ok &= check("star", execute(sel([col(Star())], "t"), d),
                    ["id", "name", "category", "price"],
                    [(1, "widget", "tools", 25),
                     (2, "gadget", "toys", 12.5),
                     (3, "doohickey", "tools", 7),
                     (4, None, "toys", None)])

        # conversions
        ok &= check("conversions", execute(sel([col(Star())], "n"), d),
                    ["a", "b", "c"],
                    [(-2, 1.5, "hello"), (0, 0.5, 3), (None, 1.0, "x")])

        # count empty
        q = sel([col(fn("COUNT", Star(), text="COUNT(*)"), None)], "t",
                where=lit(False, "FALSE"))
        ok &= check("count empty", execute(q, d), ["COUNT(*)"], [(0,)])

        # sum empty
        q = sel([col(fn("SUM", nm("price"), text="SUM(price)"))], "t",
                where=lit(False, "FALSE"))
        ok &= check("sum empty", execute(q, d), ["SUM(price)"], [(None,)])

        # count(expr) ignores nulls
        q = sel([col(fn("COUNT", nm("price"), text="COUNT(price)"))], "t")
        ok &= check("count expr", execute(q, d), ["COUNT(price)"], [(3,)])

        # group by
        q = sel([col(nm("category")),
                 col(fn("COUNT", Star(), text="COUNT(*)"), "n"),
                 col(fn("SUM", nm("price"), text="SUM(price)"), "total")],
                "t", group_by=[nm("category")],
                order_by=[order(nm("category"))])
        ok &= check("group by", execute(q, d), ["category", "n", "total"],
                    [("toys", 2, 12.5), ("tools", 2, 32)])

        # group by function, projection function
        q = sel([col(fn("LOWER", nm("category"), text="LOWER(category)")),
                 col(fn("COUNT", Star(), text="COUNT(*)"), "n")],
                "t", group_by=[nm("category")],
                order_by=[order(lit(1))])
        ok &= check("group by name, select lower", execute(q, d),
                    ["LOWER(category)", "n"], [("toys", 2), ("tools", 2)])

        # group by same function expression
        q = sel([col(fn("LOWER", nm("category"), text="LOWER(category)")),
                 col(fn("COUNT", Star(), text="COUNT(*)"), "n")],
                "t", group_by=[fn("LOWER", nm("category"))],
                order_by=[order(lit(1))])
        ok &= check("group by same func", execute(q, d),
                    ["LOWER(category)", "n"], [("toys", 2), ("tools", 2)])

        # invalid grouped column
        q = sel([col(nm("price"))], "t", group_by=[nm("category")])
        ok &= check_error("grouped non-grouped column", lambda: execute(q, d))

        # having
        q = sel([col(nm("category")),
                 col(fn("COUNT", Star(), text="COUNT(*)"), "n")],
                "t", group_by=[nm("category")],
                having=bin(">", fn("COUNT", Star()), lit(1)),
                order_by=[order(nm("category"))])
        ok &= check("having group", execute(q, d), ["category", "n"],
                    [("toys", 2), ("tools", 2)])

        q = sel([col(nm("name"))], "t",
                having=bin(">", nm("price"), lit(20)))
        ok &= check("having row filter", execute(q, d), ["name"], [("widget",)])

        # distinct + order by non-output
        q = sel([col(nm("category"))], "t", distinct=True,
                order_by=[order(nm("price"), True)])
        ok &= check("distinct order non-output", execute(q, d),
                    ["category"], [("tools",), ("toys",)])

        # order by position, alias, nulls
        q = sel([col(nm("name"), "n"), col(nm("price"), "p")], "t",
                order_by=[order(nm("p"))])
        ok &= check("order nulls asc", execute(q, d), ["n", "p"],
                    [(None, None), ("doohickey", 7), ("gadget", 12.5),
                     ("widget", 25)])
        q = sel([col(nm("name"), "n"), col(nm("price"), "p")], "t",
                order_by=[order(nm("p"), True)])
        ok &= check("order nulls desc", execute(q, d), ["n", "p"],
                    [("widget", 25), ("gadget", 12.5), ("doohickey", 7),
                     (None, None)])

        # limit offset
        q = sel([col(nm("id"))], "t", order_by=[order(lit(1))],
                limit=2, offset=1)
        ok &= check("limit offset", execute(q, d), ["id"], [(2,), (3,)])

        # aggregate errors
        q = sel([col(nm("id"))], "t",
                where=bin(">", fn("COUNT", Star()), lit(0)))
        ok &= check_error("aggregate in where", lambda: execute(q, d))
        q = sel([col(fn("SUM", fn("COUNT", Star()), text="SUM(COUNT(*))"))], "t")
        ok &= check_error("nested aggregate", lambda: execute(q, d))
        q = sel([col(nm("category"))], "t",
                group_by=[fn("COUNT", Star())])
        ok &= check_error("aggregate in group by", lambda: execute(q, d))
        q = sel([col(fn("SUM", Star(), text="SUM(*)"))], "t")
        ok &= check_error("sum star", lambda: execute(q, d))
        q = sel([col(fn("COUNT", nm("id"), nm("name")))], "t")
        ok &= check_error("count arity", lambda: execute(q, d))

        # unknown column even with no rows
        q = sel([col(nm("nope"))], "t", where=lit(False))
        ok &= check_error("unknown select column no rows", lambda: execute(q, d))
        q = sel([col(nm("id"))], "t", order_by=[order(nm("nope"))])
        ok &= check_error("unknown order column", lambda: execute(q, d))
        q = sel([col(nm("id"))], "t", having=bin("=", nm("nope"), lit(1)))
        ok &= check_error("unknown having column", lambda: execute(q, d))

        # missing / malformed / empty csv
        ok &= check_error("missing table", lambda: execute(sel([col(Star())], "zzz"), d))
        ok &= check_error("empty file", lambda: execute(sel([col(Star())], "empty"), d))
        ok &= check_error("malformed row", lambda: execute(sel([col(Star())], "bad"), d))

        # out of range order position
        q = sel([col(nm("id"))], "t", order_by=[order(lit(2))])
        ok &= check_error("order position range", lambda: execute(q, d))

        # empty group with group by -> no rows
        q = sel([col(nm("category")), col(fn("COUNT", Star()))], "t",
                where=lit(False), group_by=[nm("category")])
        ok &= check("group by empty", execute(q, d), ["category", "COUNT()"], [])

        # no group by but grouped by having aggregate
        q = sel([col(fn("COUNT", Star(), text="COUNT(*)"))], "t",
                having=bin(">", fn("COUNT", Star()), lit(0)))
        ok &= check("having aggregate", execute(q, d), ["COUNT(*)"], [(4,)])

        # distinct first occurrence
        q = sel([col(nm("category"))], "t", distinct=True)
        ok &= check("distinct order", execute(q, d), ["category"],
                    [("tools",), ("toys",)])

    print("ALL PASS" if ok else "SOME FAILURES")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

